#!/usr/bin/env bash
# Diski 9 Stage F3 (owner computer): create the two age backup-decryption identities.
#
#   deploy/f3/owner/f3-make-age-identities.sh [OUTPUT_DIR]
#
# For each identity ("primary" and "offline-recovery") the private key is generated by
# age-keygen and piped straight into "age -p" (passphrase encryption, scrypt): the
# plaintext private key exists only in memory and is never written to any disk.
# age asks for each passphrase on the terminal: generate two long random passphrases
# in your password manager first (different for each identity).
#
# Output (OUTPUT_DIR, default ./diski9-f3-age):
#   diski9-f3-age-primary.age            passphrase-encrypted identity -> password manager
#   diski9-f3-age-offline-recovery.age   passphrase-encrypted identity -> offline copy
#   diski9-f3-age-recipients.txt         the two PUBLIC recipients -> the VPS (not secret)
# Finally the script encrypts a canary to both recipients and decrypts it with each
# identity (you type each passphrase once more), proving both copies work.
set -euo pipefail
here=$(cd "$(dirname "$0")" && pwd)
# shellcheck source=lib-ramdir.sh
. "$here/lib-ramdir.sh"

command -v age >/dev/null && command -v age-keygen >/dev/null \
  || f3_die "install age (macOS: brew install age; Ubuntu: apt install age)"
out=${1:-./diski9-f3-age}
[ -e "$out" ] && f3_die "$out already exists: refusing to overwrite identities"
umask 077
mkdir -p "$out"
f3_ramdir_create

recipients="$out/diski9-f3-age-recipients.txt"
: > "$recipients"
for name in primary offline-recovery; do
  echo "== identity '$name': enter its passphrase (from your password manager) twice"
  # age-keygen writes the public key line to stderr when stdout is not a terminal
  age-keygen 2> "$F3_RAMDIR/$name.pub" | age -p -a -o "$out/diski9-f3-age-$name.age"
  pub=$(sed -n 's/^Public key: //p' "$F3_RAMDIR/$name.pub")
  case "$pub" in age1*) ;; *) f3_die "no public key produced for $name" ;; esac
  echo "# diski9-f3 $name" >> "$recipients"
  echo "$pub" >> "$recipients"
done

echo "== round-trip check: decrypt a canary with each identity (enter each passphrase)"
canary="diski9-f3-canary-$(date -u +%Y%m%dT%H%M%SZ)"
printf '%s\n' "$canary" | age -R "$recipients" -o "$F3_RAMDIR/canary.age"
for name in primary offline-recovery; do
  got=$(age -d -i "$out/diski9-f3-age-$name.age" "$F3_RAMDIR/canary.age")
  [ "$got" = "$canary" ] || f3_die "identity $name failed the round trip"
  echo "   $name: OK"
done
chmod 0644 "$recipients"

echo
echo "Done. Public recipients (safe to share and to copy to the VPS):"
grep '^age1' "$recipients"
echo
echo "Next (see docs/operations_f3_owner_setup.md, step O-2):"
echo " * store diski9-f3-age-primary.age in your password manager (attachment) and its"
echo "   passphrase in the password manager;"
echo " * copy diski9-f3-age-offline-recovery.age to the offline medium and record its"
echo "   passphrase on paper, stored separately from that medium;"
echo " * then delete the two .age files from this folder (they are encrypted; deletion is"
echo "   housekeeping, not a secrecy control)."
